// M1a · Parse & clean CSV, then dedupe inside the file.
// Input: one item from the Form Trigger with the CSV as binary + "Event name".
// Output: one item per unique person, with clean fields and "before" completeness.

const PERSONAL_DOMAINS = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'rediffmail.com', 'proton.me'];
const DEMO_SUFFIX = '.example.com'; // demo-safe emails: name@company.com.example.com
const DIAL_CODES = { '+91': 'India', '+65': 'Singapore', '+60': 'Malaysia', '+63': 'Philippines', '+62': 'Indonesia',
  '+84': 'Vietnam', '+66': 'Thailand', '+971': 'United Arab Emirates', '+966': 'Saudi Arabia', '+974': 'Qatar',
  '+1': 'United States', '+44': 'United Kingdom' };
const COUNTRY_ALIASES = { 'uae': 'United Arab Emirates', 'u.a.e.': 'United Arab Emirates', 'usa': 'United States',
  'us': 'United States', 'uk': 'United Kingdom', 'ksa': 'Saudi Arabia' };
// The 14 fields an SDR needs. "Before" = what the raw export gives us.
const COMPLETENESS_FIELDS = ['firstname', 'lastname', 'email', 'jobtitle', 'company', 'country', 'job_function',
  'seniority', 'company_industry', 'company_size_band', 'icp_tier', 'region', 'hubspot_owner_id', 'lifecyclestage'];

// ---------- helpers ----------
function parseCsv(text) {
  const rows = []; let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') q = false;
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some(v => v !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  if (field !== '' || row.length) { row.push(field); if (row.some(v => v !== '')) rows.push(row); }
  const header = rows.shift().map(h => h.trim().replace(/^﻿/, ''));
  return rows.map(r => Object.fromEntries(header.map((h, i) => [h, (r[i] ?? '').trim()])));
}
const squash = s => (s || '').replace(/\s+/g, ' ').trim();
const titleCase = s => squash(s).toLowerCase().replace(/(^|[\s\-'])([a-z])/g, (m, p, ch) => p + ch.toUpperCase());
const normOrg = s => squash(s).toLowerCase().replace(/['’.]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\b(ltd|limited|pvt|private|inc|corp|corporation|co|plc|llc|holding|holdings|group|e retail)\b/g, ' ')
  .replace(/\s+/g, ' ').trim();
function jaroWinkler(a, b) {
  a = a || ''; b = b || ''; if (a === b) return 1; if (!a || !b) return 0;
  const md = Math.max(Math.floor(Math.max(a.length, b.length) / 2) - 1, 0);
  const am = new Array(a.length).fill(false), bm = new Array(b.length).fill(false); let m = 0;
  for (let i = 0; i < a.length; i++) for (let j = Math.max(0, i - md); j < Math.min(b.length, i + md + 1); j++)
    if (!bm[j] && a[i] === b[j]) { am[i] = bm[j] = true; m++; break; }
  if (!m) return 0;
  let t = 0, k = 0;
  for (let i = 0; i < a.length; i++) if (am[i]) { while (!bm[k]) k++; if (a[i] !== b[k]) t++; k++; }
  const jaro = (m / a.length + m / b.length + (m - t / 2) / m) / 3;
  let l = 0; while (l < 4 && a[l] === b[l]) l++;
  return jaro + l * 0.1 * (1 - jaro);
}
// Company similarity: token containment, so "Nykaa" ~ "Nykaa E-Retail" and "TATA STEEL" ~ "Tata Steel Limited".
function orgSim(a, b) {
  const A = new Set(normOrg(a).split(' ').filter(Boolean)), B = new Set(normOrg(b).split(' ').filter(Boolean));
  if (!A.size || !B.size) return 0;
  const inter = [...A].filter(x => B.has(x)).length;
  return inter / Math.min(A.size, B.size);
}
const nameKey = (f, l) => [f, l].join(' ').toLowerCase().split(/\s+/).filter(Boolean).sort().join(' ');

// ---------- read the upload ----------
const upload = $input.first();
const binKey = Object.keys(upload.binary || {})[0];
if (!binKey) throw new Error('No CSV file found in the form submission');
const csvText = (await this.helpers.getBinaryDataBuffer(0, binKey)).toString('utf8');
const eventName = squash(upload.json['Event name']) || 'Untitled event';
const runId = 'm1-' + new Date().toISOString().replace(/[-:T]/g, '').slice(0, 12);
const raw = parseCsv(csvText);

// ---------- clean each row ----------
const cleaned = raw.map((r, i) => {
  const email = (r['Email'] || '').toLowerCase().replace(/\s+/g, '');
  let host = email.split('@')[1] || '';
  if (host.endsWith(DEMO_SUFFIX)) host = host.slice(0, -DEMO_SUFFIX.length);
  const isPersonal = PERSONAL_DOMAINS.includes(host);
  let country = squash(r['Country/Region Name']), countrySource = country ? 'input' : '';
  if (country && COUNTRY_ALIASES[country.toLowerCase()]) country = COUNTRY_ALIASES[country.toLowerCase()];
  if (!country && r['Phone']) {
    const code = Object.keys(DIAL_CODES).sort((a, b) => b.length - a.length).find(c => r['Phone'].startsWith(c));
    if (code) { country = DIAL_CODES[code]; countrySource = 'phone_dial_code'; }
  }
  const role = (r['Role'] || 'Attendee').toLowerCase() === 'panelist' ? 'speaker'
    : ((r['Attended'] || '').toLowerCase() === 'yes' ? 'attended' : 'no_show');
  return {
    src_row: i + 2,
    firstname: titleCase(r['First Name']), lastname: titleCase(r['Last Name']),
    email, email_is_personal: isPersonal, company_domain: isPersonal ? '' : host,
    jobtitle: squash(r['Job Title']), company: squash(r['Organization']),
    country, country_source: countrySource, phone: squash(r['Phone']),
    attendance: role,
    time_in_session_min: Number(r['Time in Session (minutes)']) || 0,
    questions_asked: Number(r['Questions Asked']) || 0,
    registered_at: r['Registration Time'],
  };
});

// ---------- dedupe inside the file ----------
// Same email, or same person (name match, either order) at the same company.
const groups = [];
for (const c of cleaned) {
  const g = groups.find(g => g.some(o =>
    (o.email && o.email === c.email) ||
    (jaroWinkler(nameKey(o.firstname, o.lastname), nameKey(c.firstname, c.lastname)) >= 0.93 &&
      (orgSim(o.company, c.company) >= 0.6 || (o.company_domain && o.company_domain === c.company_domain)))));
  if (g) g.push(c); else groups.push([c]);
}
const rank = c => (c.attendance === 'speaker' ? 4 : c.attendance === 'attended' ? 2 : 0) + (c.email_is_personal ? 0 : 1) + c.time_in_session_min / 100;
const people = groups.map(g => {
  const sorted = [...g].sort((a, b) => rank(b) - rank(a));
  const p = { ...sorted[0] };
  for (const o of sorted.slice(1)) for (const k of ['jobtitle', 'company', 'country', 'phone', 'company_domain'])
    if (!p[k] && o[k]) { p[k] = o[k]; if (k === 'country') p.country_source = o.country_source; }
  p.questions_asked = Math.max(...g.map(x => x.questions_asked));
  p.infile_duplicates = g.length - 1;
  p.infile_merge_note = g.length > 1
    ? `Merged ${g.length} registrations (rows ${g.map(x => x.src_row).join(', ')}): ` +
      (new Set(g.map(x => x.email)).size === 1 ? 'same email' : 'same person at same company, different email')
    : '';
  p.other_emails = [...new Set(g.map(x => x.email))].filter(e => e !== p.email);
  const have = { firstname: p.firstname, lastname: p.lastname, email: p.email, jobtitle: p.jobtitle, company: p.company,
    country: p.country_source === 'input' ? p.country : '' };
  p.fields_missing_before = COMPLETENESS_FIELDS.filter(f => !have[f]);
  p.data_completeness_before_pct = Math.round(100 * (COMPLETENESS_FIELDS.length - p.fields_missing_before.length) / COMPLETENESS_FIELDS.length);
  p.event_name = eventName; p.m1_run_id = runId;
  return p;
});

return people.map(p => ({ json: { ...p, _stats: { raw_rows: raw.length, unique_people: people.length } } }));

// M1a · Match each person against existing HubSpot contacts.
// Rules (confidence):
//   1.00  exact email match                      -> update existing (Merged)
//   0.95  same full name + same company          -> update existing (Merged)
//   0.80  similar name (JW >= 0.85) + same company -> create, flag "Needs review"
//   else  create new
// Output: one item per person with hs_props ready to create/update.

const normOrg = s => (s || '').toLowerCase().replace(/['’.]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\b(ltd|limited|pvt|private|inc|corp|corporation|co|plc|llc|holding|holdings|group|e retail|bank)\b/g, ' ')
  .replace(/\s+/g, ' ').trim();
function orgSim(a, b) {
  const A = new Set(normOrg(a).split(' ').filter(Boolean)), B = new Set(normOrg(b).split(' ').filter(Boolean));
  if (!A.size || !B.size) return 0;
  return [...A].filter(x => B.has(x)).length / Math.min(A.size, B.size);
}
function jaroWinkler(a, b) {
  a = a || ''; b = b || ''; if (a === b) return 1; if (!a || !b) return 0;
  const md = Math.max(Math.floor(Math.max(a.length, b.length) / 2) - 1, 0);
  const am = new Array(a.length).fill(false), bm = new Array(b.length).fill(false); let m = 0;
  for (let i = 0; i < a.length; i++) for (let j = Math.max(0, i - md); j < Math.min(b.length, i + md + 1); j++)
    if (!bm[j] && a[i] === b[j]) { am[i] = bm[j] = true; m++; break; }
  if (!m) return 0;
  let t = 0, k = 0;
  for (let i = 0; i < a.length; i++) if (am[i]) { while (!bm[k]) k++; if (a[i] !== b[k]) t++; k++; }
  const jaro = (m / a.length + m / b.length + (m - t / 2) / m) / 3;
  let l = 0; while (l < 4 && a[l] === b[l]) l++;
  return jaro + l * 0.1 * (1 - jaro);
}
const full = (f, l) => `${f || ''} ${l || ''}`.toLowerCase().replace(/\s+/g, ' ').trim();
const domainOf = e => ((e || '').split('@')[1] || '').replace(/\.example\.com$/, '');

const crm = ($('Load CRM contacts').first().json.results || []).map(c => ({ id: c.id, ...c.properties }));
const people = $('Parse & clean CSV').all().map(i => i.json);

return people.map(p => {
  let match = null, confidence = 0, reason = 'No match in HubSpot: new contact';
  const byEmail = crm.find(c => (c.email || '').toLowerCase() === p.email || p.other_emails.includes((c.email || '').toLowerCase()));
  if (byEmail) { match = byEmail; confidence = 1; reason = `Exact email match with HubSpot contact ${byEmail.id}`; }
  else {
    let best = null, bestScore = 0, bestKind = '';
    for (const c of crm) {
      const nameJW = jaroWinkler(full(p.firstname, p.lastname), full(c.firstname, c.lastname));
      const sameCo = Math.max(orgSim(p.company, c.company), p.company_domain && p.company_domain === domainOf(c.email) ? 1 : 0);
      if (sameCo < 0.6) continue;
      if (nameJW === 1 && 0.95 > bestScore) { best = c; bestScore = 0.95; bestKind = 'same name, same company'; }
      else if (nameJW >= 0.85 && 0.8 > bestScore) { best = c; bestScore = 0.8; bestKind = `similar name (${nameJW.toFixed(2)}), same company`; }
    }
    if (best) {
      confidence = bestScore;
      if (bestScore >= 0.9) { match = best; reason = `Fuzzy match: ${bestKind} as HubSpot contact ${best.id} (${best.firstname} ${best.lastname}, ${best.company})`; }
      else reason = `Possible duplicate of HubSpot contact ${best.id} (${best.firstname} ${best.lastname}, ${best.company}): ${bestKind}. Created separately for SDR review.`;
    }
  }
  const status = match ? 'merged' : (confidence >= 0.75 ? 'needs_review' : 'new');
  if (p.infile_merge_note) reason = `${p.infile_merge_note}. ${reason}`;

  const props = {
    firstname: p.firstname, lastname: p.lastname, jobtitle: p.jobtitle, company: p.company,
    phone: p.phone || undefined,
    country: p.country || undefined,
    event_name: p.event_name, event_attendance_status: p.attendance,
    time_in_session_min: p.attendance === 'no_show' ? 0 : p.time_in_session_min,
    questions_asked: p.questions_asked,
    dedupe_status: status, dedupe_reason: reason, match_confidence: confidence,
    data_completeness_before_pct: p.data_completeness_before_pct,
    fields_missing_before: JSON.stringify(p.fields_missing_before),
    m1_run_id: p.m1_run_id,
    enrichment_source: 'input',
  };
  if (!match) props.email = p.email;               // never overwrite the CRM's email on a merge
  if (match && !props.jobtitle) delete props.jobtitle;
  Object.keys(props).forEach(k => props[k] === undefined && delete props[k]);

  return { json: { ...p, hubspot_id: match ? match.id : null, dedupe_status: status, dedupe_reason: reason,
                   match_confidence: confidence, hs_props: props } };
});

const people = $('Match vs HubSpot').all().map(i => i.json);
const saved = $('Create or update contact').all().filter(i => i.json.id).length;
const s = k => people.filter(p => p.dedupe_status === k).length;
const avg = Math.round(people.reduce((a, p) => a + p.data_completeness_before_pct, 0) / people.length);
return [{ json: { message:
  `${people[0]._stats.raw_rows} rows received → ${people.length} unique people (${people[0]._stats.raw_rows - people.length} duplicate registrations merged).\n` +
  `HubSpot: ${s('merged')} matched existing contacts, ${s('needs_review')} flagged for review, ${s('new')} new. ${saved} saved.\n` +
  `Data completeness before enrichment: ${avg}%. Clay + DeepSeek are enriching now; open the M1 report in ~2 minutes.` } }];

// M1b · Merge the Clay callback with the HubSpot contact and build the DeepSeek classification request.
// Runs once per item (Clay calls back one row at a time).

const clay = $('Clay callback').item.json.body || {};
const contact = $json.properties || {};

// Clay returns sizes as numbers or ranges ("1,001-5,000", "10001+"). Keep the lower bound.
const parseCount = v => {
  if (v === null || v === undefined || v === '') return null;
  const nums = String(v).replace(/,/g, '').match(/\d+/g);
  return nums ? Number(nums[0]) : null;
};
const company = {
  name: clay.company_name || contact.company || '',
  domain: (clay.final_domain || '').replace(/^https?:\/\//, '').replace(/\/.*$/, '').toLowerCase(),
  employee_count: parseCount(clay.employee_count),
  industry: clay.industry || '',
  hq_country: clay.hq_country || '',
  linkedin_url: clay.linkedin_url || '',
  description: (clay.description || '').slice(0, 600),
};

const system = `You normalise B2B lead data for Darwinbox, an enterprise HCM (HR software) platform.
Its buyers are HR leaders and HR tech owners at mid-size and large enterprises in India, Southeast Asia, the Middle East and the US.
Return ONLY a JSON object with exactly these keys:
{
 "normalized_title": string | null,           // clean, readable job title, e.g. "Senior Manager, HR"
 "job_function": one of ["HR","HRIS","Talent Acquisition","L&D","Total Rewards","Finance","IT","Operations","Leadership","Student","Consulting","Other"],
 "seniority": one of ["C-level","VP","Director","Manager","IC","Unknown"],
 "industry": string | null,                   // short normalised industry, e.g. "IT Services", "Banking & Financial Services"
 "employee_count_estimate": integer | null,   // ONLY if company.employee_count is null and you know the company well
 "contact_country": string | null,            // ONLY if contact.country is empty; use the company HQ country
 "disqualifier": one of ["none","student","consultant_or_agency","hr_tech_vendor","personal_use"],
 "inferred": [ { "field": string, "value": string, "confidence": number, "basis": string } ],
 "fit_note": string                            // one sentence: why this person/company is or is not a fit for Darwinbox
}
Rules:
- Use the given data first. Only infer what is missing, and list every inferred value in "inferred" with a 0-1 confidence and a short basis.
- If the title is empty, infer function/seniority only if the company + context make it reasonable; otherwise use "Other"/"Unknown".
- Never invent facts about the person. In fit_note, refer to the contact by role, not by gendered pronouns.
- No markdown, no extra keys.`;

const user = JSON.stringify({
  contact: {
    name: `${contact.firstname || ''} ${contact.lastname || ''}`.trim(),
    job_title: contact.jobtitle || '',
    company: contact.company || '',
    country: contact.country || '',
    attendance: contact.event_attendance_status || '',
  },
  company,
});

return {
  json: {
    hs_contact_id: clay.row_id || $json.id,
    contact, company,
    request_body: {
      model: 'deepseek-flash',
      response_format: { type: 'json_object' },
      temperature: 0.1,
      max_tokens: 1500,
      thinking: { type: 'disabled' },   // classification needs no reasoning; keeps it fast and the JSON complete
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
    },
  },
};

// M1b · Validate the DeepSeek output, score ICP fit, assign region + owner + lifecycle stage,
// and build the HubSpot company + contact updates. Runs once per item.

// ---------- editable config (show this in the demo) ----------
const ICP = {
  size:      [[5000, 30], [1000, 25], [500, 18], [200, 8], [0, 0]],           // employees >= n -> points
  region:    { india: 15, sea: 15, mea: 15, na: 10, row: 5 },
  persona:   { 'HR': 20, 'HRIS': 20, 'Talent Acquisition': 18, 'L&D': 16, 'Total Rewards': 18, 'Leadership': 15,
               'Finance': 10, 'IT': 10, 'Operations': 6, 'Consulting': 0, 'Student': 0, 'Other': 0 },
  seniority: { 'C-level': 15, 'VP': 15, 'Director': 12, 'Manager': 7, 'IC': 2, 'Unknown': 0 },
  engagement: { attended: 8, stayed_30_min: 6, asked_question: 6 },          // intent matters as much as fit
  tiers: { A: 75, B: 50 },                                                    // >= A -> A, >= B -> B, else C
  hr_persona_min: 15,                                                         // persona points needed for Tier A
};
const OWNERS = { senior: '169348475', india: '169348477', international: '169348476', speakers: '100973776' };
const REGION_OF = {
  'India': 'india', 'Singapore': 'sea', 'Malaysia': 'sea', 'Philippines': 'sea', 'Indonesia': 'sea', 'Vietnam': 'sea',
  'Thailand': 'sea', 'United Arab Emirates': 'mea', 'UAE': 'mea', 'Saudi Arabia': 'mea', 'Qatar': 'mea', 'Kuwait': 'mea',
  'Oman': 'mea', 'Bahrain': 'mea', 'Egypt': 'mea', 'South Africa': 'mea', 'United States': 'na', 'Canada': 'na',
};
const STAGES = ['subscriber', 'lead', 'marketingqualifiedlead', 'salesqualifiedlead', 'opportunity', 'customer', 'evangelist', 'other'];
const ENUMS = {
  job_function: Object.keys(ICP.persona),
  seniority: Object.keys(ICP.seniority),
  disqualifier: ['none', 'student', 'consultant_or_agency', 'hr_tech_vendor', 'personal_use'],
};
// The same 14 fields M1a measured "before".
const COMPLETENESS_FIELDS = ['firstname', 'lastname', 'email', 'jobtitle', 'company', 'country', 'job_function',
  'seniority', 'company_industry', 'company_size_band', 'icp_tier', 'region', 'hubspot_owner_id', 'lifecyclestage'];

// ---------- inputs ----------
const prev = $('Build prompt').item.json;
const c = prev.contact, co = prev.company;
let ai = {}, aiError = '';
try { ai = JSON.parse($json.choices[0].message.content); } catch (e) { aiError = 'DeepSeek returned invalid JSON; used fallbacks'; }
const pick = (v, allowed, fallback) => (allowed.includes(v) ? v : fallback);
const fn = pick(ai.job_function, ENUMS.job_function, 'Other');
const sen = pick(ai.seniority, ENUMS.seniority, 'Unknown');
const disq = pick(ai.disqualifier, ENUMS.disqualifier, 'none');
const inferred = Array.isArray(ai.inferred) ? ai.inferred.filter(x => x && x.field).slice(0, 10) : [];

// ---------- company facts: Clay first, AI fallback ----------
let employees = co.employee_count, sizeSource = employees ? 'clay' : '';
if (!employees && Number.isInteger(ai.employee_count_estimate)) { employees = ai.employee_count_estimate; sizeSource = 'llm'; }
const band = employees == null ? null : employees >= 5000 ? '5000plus' : employees >= 1000 ? '1000_4999'
  : employees >= 500 ? '500_999' : employees >= 200 ? '200_499' : '1_199';
const industry = co.industry || ai.industry || null;
const industrySource = co.industry ? 'clay' : (ai.industry ? 'llm' : '');

// ---------- region + country ----------
let country = c.country || '', countrySource = country ? 'input' : '';
if (!country && ai.contact_country) { country = ai.contact_country; countrySource = 'llm'; }
if (!country && co.hq_country) { country = co.hq_country; countrySource = 'clay_hq'; }
const region = REGION_OF[country] || 'row';

// ---------- ICP score ----------
const attendance = c.event_attendance_status;
const isSpeaker = attendance === 'speaker';
const pts = {
  company_size: employees == null ? 0 : ICP.size.find(([n]) => employees >= n)[1],
  region: ICP.region[region] ?? 0,
  persona: ICP.persona[fn] ?? 0,
  seniority: ICP.seniority[sen] ?? 0,
  engagement: (attendance === 'attended' ? ICP.engagement.attended : 0)
    + (Number(c.time_in_session_min) >= 30 ? ICP.engagement.stayed_30_min : 0)
    + (Number(c.questions_asked) > 0 ? ICP.engagement.asked_question : 0),
};
let score = Object.values(pts).reduce((a, b) => a + b, 0);
if (disq !== 'none') { score = Math.min(score, ICP.tiers.B - 1); pts.disqualifier_cap = disq; }
let tier = score >= ICP.tiers.A ? 'a' : score >= ICP.tiers.B ? 'b' : 'c';
// Tier A needs an HR-buyer persona: a big company alone is not enough.
if (tier === 'a' && pts.persona < ICP.hr_persona_min) { tier = 'b'; pts.tier_rule = 'A needs HR-buyer persona'; }

// ---------- owner + lifecycle (forward only) ----------
const owner = isSpeaker ? OWNERS.speakers : tier === 'a' ? OWNERS.senior : region === 'india' ? OWNERS.india : OWNERS.international;
// MQL = attended + Tier A/B + we know their role. Unknown role stays a lead until an SDR qualifies it.
const target = isSpeaker ? 'other'
  : attendance === 'attended' && (tier === 'a' || tier === 'b') && fn !== 'Other' ? 'marketingqualifiedlead' : 'lead';
const current = c.lifecyclestage || '';
const moveStage = !current || STAGES.indexOf(target) > STAGES.indexOf(current);

// ---------- HubSpot payloads ----------
const sourceTags = new Set(['input']);
if (sizeSource === 'clay' || industrySource === 'clay' || co.domain) sourceTags.add('clay');
if (inferred.length || sizeSource === 'llm' || industrySource === 'llm' || countrySource === 'llm') sourceTags.add('llm');
const contactProps = {
  job_function: fn, seniority: sen,
  jobtitle: c.jobtitle || ai.normalized_title || undefined,
  country: country || undefined,
  company_industry: industry || undefined,
  company_size_band: band || undefined,
  icp_tier: isSpeaker ? undefined : tier,
  icp_score: isSpeaker ? undefined : score,
  icp_breakdown: JSON.stringify(pts),
  icp_reason: isSpeaker ? 'Speaker: excluded from ICP scoring' : `${tier.toUpperCase()} (${score}/100${pts.tier_rule ? '; ' + pts.tier_rule : ''}${pts.disqualifier_cap ? '; capped: ' + disq : ''}). ${ai.fit_note || ''}`.trim(),
  region,
  hubspot_owner_id: owner,
  inferred_fields: JSON.stringify([
    ...inferred,
    ...(countrySource === 'llm' || countrySource === 'clay_hq' ? [{ field: 'country', value: country, confidence: 0.7, basis: 'company HQ' }] : []),
    ...(sizeSource === 'llm' ? [{ field: 'company_size', value: String(employees), confidence: 0.6, basis: 'LLM estimate, Clay had no data' }] : []),
  ]),
  enrichment_source: [...sourceTags].join('+'),
};
if (moveStage) contactProps.lifecyclestage = target;
if (aiError) contactProps.inferred_fields = JSON.stringify([{ field: 'all', value: aiError, confidence: 0, basis: 'fallback' }]);

const after = { ...c, ...contactProps, lifecyclestage: moveStage ? target : current };
const filled = COMPLETENESS_FIELDS.filter(f => after[f] !== undefined && after[f] !== null && after[f] !== '' && after[f] !== 'Unknown');
contactProps.data_completeness_pct = Math.round(100 * filled.length / COMPLETENESS_FIELDS.length);
Object.keys(contactProps).forEach(k => contactProps[k] === undefined && delete contactProps[k]);

const companyProps = {
  name: co.name || c.company, domain: co.domain || undefined,
  employee_band: band || undefined, numberofemployees: employees || undefined,
  industry_normalised: industry || undefined, hq_country: co.hq_country || undefined,
  linkedin_company_page: co.linkedin_url || undefined,
  description: co.description || undefined,
  enrichment_source: sizeSource === 'llm' || industrySource === 'llm' ? 'clay+llm' : 'clay',
};
Object.keys(companyProps).forEach(k => companyProps[k] === undefined && delete companyProps[k]);

return { json: { hs_contact_id: prev.hs_contact_id, company_domain: co.domain, company_name: companyProps.name,
                 contact_props: contactProps, company_props: companyProps } };

// M1c · Build the M1 report page from HubSpot: completeness before vs after, dedupe results,
// ICP tiers, routing, and the SDR handoff list (+ HubSpot-ready CSV download).

const FIELDS = ['firstname', 'lastname', 'email', 'jobtitle', 'company', 'country', 'job_function', 'seniority',
  'company_industry', 'company_size_band', 'icp_tier', 'region', 'hubspot_owner_id', 'lifecyclestage'];
const LABEL = { firstname: 'First name', lastname: 'Last name', email: 'Email', jobtitle: 'Job title', company: 'Company',
  country: 'Country', job_function: 'Job function', seniority: 'Seniority', company_industry: 'Industry',
  company_size_band: 'Company size', icp_tier: 'ICP tier', region: 'Region', hubspot_owner_id: 'Owner', lifecyclestage: 'Lifecycle stage' };
const OWNER = { '169348475': 'Neha (Senior SDR)', '169348477': 'Priya (India SDR)', '169348476': 'Aman (SEA/MEA SDR)', '100973776': 'Rahul (speakers)' };
const STAGE = { subscriber: 'Subscriber', lead: 'Lead', marketingqualifiedlead: 'MQL', salesqualifiedlead: 'SQL', other: 'Other' };
const SIZE = { '1_199': '1-199', '200_499': '200-499', '500_999': '500-999', '1000_4999': '1,000-4,999', '5000plus': '5,000+' };
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const has = v => v !== undefined && v !== null && v !== '' && v !== 'Unknown';

const event = $('Report request').first().json.query?.event || 'Darwinbox Cortex and the AI-Native Era of HCM';
const contacts = $input.all().flatMap(i => i.json.results || []).map(r => ({ id: r.id, ...r.properties }));
const n = contacts.length || 1;

// completeness per field, before vs after
const rows = FIELDS.map(f => {
  const before = contacts.filter(c => { try { return !JSON.parse(c.fields_missing_before || '[]').includes(f); } catch { return false; } }).length;
  const after = contacts.filter(c => has(c[f])).length;
  return { f, before: Math.round(100 * before / n), after: Math.round(100 * after / n) };
});
const avg = k => Math.round(rows.reduce((s, r) => s + r[k], 0) / rows.length);
const count = (k, v) => contacts.filter(c => c[k] === v).length;
const scored = contacts.filter(c => c.event_attendance_status !== 'speaker');
const handoff = scored.filter(c => c.lifecyclestage === 'marketingqualifiedlead' || c.icp_tier === 'a')
  .sort((a, b) => Number(b.icp_score) - Number(a.icp_score));
const review = contacts.filter(c => c.dedupe_status === 'needs_review');
const merged = contacts.filter(c => c.dedupe_status === 'merged');

// HubSpot-ready CSV (import-friendly internal names as headers)
const csvCols = ['email', 'firstname', 'lastname', 'jobtitle', 'company', 'country', 'job_function', 'seniority',
  'company_industry', 'company_size_band', 'region', 'icp_tier', 'icp_score', 'icp_reason', 'hubspot_owner_id',
  'lifecyclestage', 'event_name', 'event_attendance_status', 'dedupe_status'];
const csv = [csvCols.join(','), ...contacts.map(c => csvCols.map(k => `"${String(c[k] ?? '').replace(/"/g, '""')}"`).join(','))].join('\n');

const bar = (p, cls) => `<div class="bar"><span class="${cls}" style="width:${p}%"></span></div><b>${p}%</b>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>M1 Lead Enrichment Report</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--ink:#14171f;--muted:#5b6475;--line:#e3e6ec;--before:#c9ced8;--after:#1f7a5a;--a:#1f7a5a;--b:#b7791f;--c:#8a93a5}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--ink:#e8ebf1;--muted:#9aa3b5;--line:#2a2f3a;--before:#3a4150;--after:#3fb68b;--a:#3fb68b;--b:#e0a542;--c:#7d8699}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:1100px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:28px 0 10px}
.sub{color:var(--muted);margin:0 0 20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}.k{color:var(--muted);font-size:12px}.v{font-size:24px;font-weight:650}
table{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden}
th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;color:var(--muted);font-weight:600}
.bar{display:inline-block;width:110px;height:8px;background:var(--line);border-radius:4px;margin-right:6px;vertical-align:middle}.bar span{display:block;height:100%;border-radius:4px}
.before{background:var(--before)}.after{background:var(--after)}.t{font-weight:700}.ta{color:var(--a)}.tb{color:var(--b)}.tc{color:var(--c)}
.wrap{overflow-x:auto}a.btn{display:inline-block;margin-top:8px;padding:8px 12px;border:1px solid var(--line);border-radius:8px;color:var(--ink);text-decoration:none;background:var(--card)}
.muted{color:var(--muted)}
</style></head><body><main>
<h1>Lead Enrichment Report</h1>
<p class="sub">${esc(event)} · ${contacts.length} contacts in HubSpot · generated ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC</p>
<div class="grid">
 <div class="card"><div class="k">Completeness before</div><div class="v">${avg('before')}%</div></div>
 <div class="card"><div class="k">Completeness after</div><div class="v">${avg('after')}%</div></div>
 <div class="card"><div class="k">Merged with existing CRM</div><div class="v">${merged.length}</div></div>
 <div class="card"><div class="k">Needs review</div><div class="v">${review.length}</div></div>
 <div class="card"><div class="k">ICP tier A / B / C</div><div class="v"><span class="ta">${count('icp_tier', 'a')}</span> / <span class="tb">${count('icp_tier', 'b')}</span> / <span class="tc">${count('icp_tier', 'c')}</span></div></div>
 <div class="card"><div class="k">MQLs for SDR handoff</div><div class="v">${count('lifecyclestage', 'marketingqualifiedlead')}</div></div>
</div>

<h2>Field completeness: before vs after</h2>
<div class="wrap"><table><tr><th>Field</th><th>Before (raw export)</th><th>After (Clay + DeepSeek + rules)</th></tr>
${rows.map(r => `<tr><td>${LABEL[r.f]}</td><td>${bar(r.before, 'before')}</td><td>${bar(r.after, 'after')}</td></tr>`).join('')}
</table></div>

<h2>SDR handoff (${handoff.length})</h2>
<div class="wrap"><table><tr><th>Contact</th><th>Company</th><th>Tier</th><th>Why</th><th>Owner</th><th>Stage</th></tr>
${handoff.map(c => `<tr><td><b>${esc(c.firstname)} ${esc(c.lastname)}</b><br><span class="muted">${esc(c.jobtitle)} · ${esc(c.job_function)} · ${esc(c.seniority)}</span></td>
<td>${esc(c.company)}<br><span class="muted">${esc(c.company_industry)} · ${esc(SIZE[c.company_size_band] || '')} · ${esc(c.country)}</span></td>
<td class="t t${esc(c.icp_tier)}">${esc((c.icp_tier || '').toUpperCase())} ${esc(c.icp_score)}</td><td>${esc((c.icp_reason || '').replace(/^[ABC] \([^)]*\)\.\s*/, ''))}</td>
<td>${esc(OWNER[c.hubspot_owner_id] || c.hubspot_owner_id)}</td><td>${esc(STAGE[c.lifecyclestage] || c.lifecyclestage)}</td></tr>`).join('')}
</table></div>

<h2>Dedupe decisions</h2>
<div class="wrap"><table><tr><th>Contact</th><th>Status</th><th>Reason</th></tr>
${[...review, ...merged].map(c => `<tr><td>${esc(c.firstname)} ${esc(c.lastname)}<br><span class="muted">${esc(c.company)}</span></td><td>${c.dedupe_status === 'merged' ? 'Merged' : 'Needs review'}</td><td>${esc(c.dedupe_reason)}</td></tr>`).join('')}
</table></div>

<h2>HubSpot-ready file</h2>
<a class="btn" download="hubspot_ready_${esc(event.toLowerCase().replace(/[^a-z0-9]+/g, '-'))}.csv" href="data:text/csv;charset=utf-8,${encodeURIComponent(csv)}">Download CSV (${contacts.length} rows)</a>
</main></body></html>`;

return [{ json: { html, contacts: contacts.length, completeness_before: avg('before'), completeness_after: avg('after') } }];
